//! 采集隐私策略：在读取剪贴板内容**之前**决定这次变化要不要跳过。
//!
//! 判断顺序：暂停 → 隐私类型（密码管理器标记的隐藏 / 临时内容）→ 排除应用。
//! 全部是纯函数，只依赖 std，不碰 AppKit —— 任何平台都能单测。
//! [`CaptureGate`] 是运行时共享的那一份状态：watcher 与 pipeline 拿的是同一个 Arc。

use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, RwLock};

use crate::domain::model::ClipboardItem;

/// nspasteboard.org 约定的隐私标记，以及 1Password 自己的类型。
/// 剪贴板上出现任一类型，这次复制就整条不记。
pub const PRIVACY_PASTEBOARD_TYPES: &[&str] = &[
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.TransientType",
    "org.nspasteboard.AutoGeneratedType",
    "com.agilebits.onepassword",
    "com.agilebits.onepassword7",
];

/// 默认「不记录这些应用」名单：钥匙串与常见密码管理器。
pub const DEFAULT_EXCLUDED_APPS: &[&str] = &[
    "com.apple.keychainaccess",
    "com.1password.1password",
    "com.agilebits.onepassword7",
    "com.bitwarden.desktop",
    "com.apple.Passwords",
];

/// 名单条目数上限与单条长度上限（字符数）。
pub const MAX_EXCLUDED_APPS: usize = 200;
pub const MAX_EXCLUDED_APP_LEN: usize = 256;

pub fn default_excluded_apps() -> Vec<String> {
    DEFAULT_EXCLUDED_APPS
        .iter()
        .map(|app| app.to_string())
        .collect()
}

/// 剪贴板类型里是否带隐私标记（大小写不敏感）。
pub fn has_privacy_marker(types: &[String]) -> bool {
    types.iter().any(|ty| {
        PRIVACY_PASTEBOARD_TYPES
            .iter()
            .any(|marker| marker.eq_ignore_ascii_case(ty))
    })
}

fn non_blank(value: Option<&str>) -> Option<&str> {
    value.map(str::trim).filter(|v| !v.is_empty())
}

/// 来源是否在排除名单里。每条既可以是 bundle id 也可以是应用名：
/// bundle id 按 ASCII 大小写不敏感比较；应用名可能是中文 / Unicode，按 `to_lowercase` 比较。
/// trim 后为空的条目、空来源都不算命中。
pub fn is_app_excluded(
    bundle_id: Option<&str>,
    app_name: Option<&str>,
    excluded: &[String],
) -> bool {
    let bundle_id = non_blank(bundle_id);
    let app_name = non_blank(app_name).map(str::to_lowercase);
    if bundle_id.is_none() && app_name.is_none() {
        return false;
    }
    excluded.iter().any(|entry| {
        let entry = entry.trim();
        if entry.is_empty() {
            return false;
        }
        bundle_id.is_some_and(|id| id.eq_ignore_ascii_case(entry))
            || app_name
                .as_deref()
                .is_some_and(|name| name == entry.to_lowercase())
    })
}

/// trim、去空串、大小写不敏感去重（保留首次出现的写法与顺序）。
pub fn normalize_excluded_apps(apps: Vec<String>) -> Vec<String> {
    let mut seen = std::collections::HashSet::new();
    apps.into_iter()
        .map(|app| app.trim().to_string())
        .filter(|app| !app.is_empty())
        .filter(|app| seen.insert(app.to_lowercase()))
        .collect()
}

/// 这次剪贴板变化为什么被跳过。日志里只记它，不记内容。
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SkipReason {
    Paused,
    PrivacyMarked,
    ExcludedApp,
}

/// 读取内容之前的跳过判断。优先级：暂停 > 隐私类型 > 排除应用。
pub fn pre_capture_skip_reason(
    capture_enabled: bool,
    pasteboard_types: &[String],
    bundle_id: Option<&str>,
    app_name: Option<&str>,
    excluded: &[String],
) -> Option<SkipReason> {
    if !capture_enabled {
        return Some(SkipReason::Paused);
    }
    if has_privacy_marker(pasteboard_types) {
        return Some(SkipReason::PrivacyMarked);
    }
    if is_app_excluded(bundle_id, app_name, excluded) {
        return Some(SkipReason::ExcludedApp);
    }
    None
}

/// 采集闸门：采集开关 + 排除名单。克隆出来的每一份共享同一组 Arc，
/// 设置一改，watcher 和 pipeline 立刻看到。
#[derive(Clone)]
pub struct CaptureGate {
    enabled: Arc<AtomicBool>,
    excluded: Arc<RwLock<Vec<String>>>,
}

impl CaptureGate {
    pub fn new(enabled: bool, excluded: Vec<String>) -> Self {
        Self {
            enabled: Arc::new(AtomicBool::new(enabled)),
            excluded: Arc::new(RwLock::new(excluded)),
        }
    }

    pub fn is_enabled(&self) -> bool {
        self.enabled.load(Ordering::SeqCst)
    }

    pub fn set_enabled(&self, enabled: bool) {
        self.enabled.store(enabled, Ordering::SeqCst);
    }

    pub fn set_excluded_apps(&self, apps: Vec<String>) {
        *self.excluded.write().unwrap_or_else(|e| e.into_inner()) = apps;
    }

    pub fn is_excluded(&self, bundle_id: Option<&str>, app_name: Option<&str>) -> bool {
        let excluded = self.excluded.read().unwrap_or_else(|e| e.into_inner());
        is_app_excluded(bundle_id, app_name, &excluded)
    }

    pub fn skip_reason(
        &self,
        pasteboard_types: &[String],
        bundle_id: Option<&str>,
        app_name: Option<&str>,
    ) -> Option<SkipReason> {
        let enabled = self.is_enabled();
        let excluded = self.excluded.read().unwrap_or_else(|e| e.into_inner());
        pre_capture_skip_reason(enabled, pasteboard_types, bundle_id, app_name, &excluded)
    }
}

/// 历史里出现过的来源应用（设置面板「从最近复制来源中添加」用）。
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SourceApp {
    pub name: Option<String>,
    pub bundle_id: Option<String>,
}

/// 从条目列表里取不重复的来源应用，保留列表顺序（最近复制的在前）。
/// 有 bundle id 按 bundle id（小写）去重，否则按应用名（小写）；两者都空的跳过。
pub fn distinct_source_apps(items: &[ClipboardItem], max: usize) -> Vec<SourceApp> {
    let mut seen = std::collections::HashSet::new();
    let mut apps = Vec::new();
    for item in items {
        if apps.len() >= max {
            break;
        }
        let bundle_id = non_blank(item.source_bundle_id.as_deref()).map(str::to_string);
        let name = non_blank(item.source_app.as_deref()).map(str::to_string);
        let key = match (&bundle_id, &name) {
            (Some(id), _) => format!("bundle:{}", id.to_lowercase()),
            (None, Some(name)) => format!("name:{}", name.to_lowercase()),
            (None, None) => continue,
        };
        if seen.insert(key) {
            apps.push(SourceApp { name, bundle_id });
        }
    }
    apps
}

#[cfg(test)]
mod tests {
    use super::*;

    fn types(list: &[&str]) -> Vec<String> {
        list.iter().map(|t| t.to_string()).collect()
    }

    fn strings(list: &[&str]) -> Vec<String> {
        types(list)
    }

    #[test]
    fn paused_short_circuits_everything() {
        let excluded = default_excluded_apps();
        for (ty, bundle, name) in [
            (types(&[]), None, None),
            (
                types(&["public.utf8-plain-text"]),
                Some("com.apple.Safari"),
                Some("Safari"),
            ),
            (
                types(&["org.nspasteboard.ConcealedType"]),
                Some("com.bitwarden.desktop"),
                None,
            ),
        ] {
            assert_eq!(
                pre_capture_skip_reason(false, &ty, bundle, name, &excluded),
                Some(SkipReason::Paused)
            );
        }
    }

    #[test]
    fn privacy_marked_types_are_skipped() {
        for marker in PRIVACY_PASTEBOARD_TYPES {
            let ty = types(&["public.utf8-plain-text", marker]);
            assert!(has_privacy_marker(&ty), "{marker}");
            assert_eq!(
                pre_capture_skip_reason(true, &ty, Some("com.apple.Safari"), None, &[]),
                Some(SkipReason::PrivacyMarked),
                "{marker}"
            );
        }
        assert!(has_privacy_marker(&types(&[
            "ORG.NSPASTEBOARD.CONCEALEDTYPE"
        ])));
        let plain = types(&["public.utf8-plain-text"]);
        assert!(!has_privacy_marker(&plain));
        assert_eq!(
            pre_capture_skip_reason(true, &plain, Some("com.apple.Safari"), None, &[]),
            None
        );
    }

    #[test]
    fn privacy_marker_wins_over_excluded_app() {
        let ty = types(&["org.nspasteboard.TransientType"]);
        assert_eq!(
            pre_capture_skip_reason(
                true,
                &ty,
                Some("com.bitwarden.desktop"),
                None,
                &default_excluded_apps()
            ),
            Some(SkipReason::PrivacyMarked)
        );
    }

    #[test]
    fn excluded_app_matches_bundle_id_case_insensitively() {
        let excluded = default_excluded_apps();
        assert!(is_app_excluded(
            Some("COM.BITWARDEN.DESKTOP"),
            None,
            &excluded
        ));
        assert!(is_app_excluded(
            Some("com.apple.passwords"),
            Some("密码"),
            &excluded
        ));
        assert_eq!(
            pre_capture_skip_reason(
                true,
                &types(&["public.utf8-plain-text"]),
                Some("com.apple.keychainaccess"),
                Some("钥匙串访问"),
                &excluded
            ),
            Some(SkipReason::ExcludedApp)
        );
    }

    #[test]
    fn excluded_app_falls_back_to_name() {
        let excluded = strings(&["1password", "钥匙串访问"]);
        assert!(is_app_excluded(None, Some("1Password"), &excluded));
        assert!(is_app_excluded(
            Some("com.unknown.app"),
            Some("1PASSWORD"),
            &excluded
        ));
        assert!(is_app_excluded(None, Some("钥匙串访问"), &excluded));
        assert!(is_app_excluded(None, Some("  钥匙串访问 "), &excluded));
    }

    #[test]
    fn unrelated_or_empty_does_not_match() {
        let excluded = default_excluded_apps();
        assert!(!is_app_excluded(
            Some("com.apple.Safari"),
            Some("Safari"),
            &excluded
        ));
        assert!(!is_app_excluded(None, None, &excluded));
        assert!(!is_app_excluded(Some("  "), Some(""), &excluded));
        assert!(
            !is_app_excluded(Some(""), Some(""), &strings(&["", "  "])),
            "空条目不命中空来源"
        );
        assert!(!is_app_excluded(
            Some("com.apple.Safari"),
            Some("Safari"),
            &strings(&["  "])
        ));
        assert!(
            !is_app_excluded(Some("com.bitwarden.desktop.helper"), None, &excluded),
            "只做精确匹配，不做前缀匹配"
        );
    }

    #[test]
    fn normalize_trims_dedupes_and_keeps_order() {
        let normalized = normalize_excluded_apps(strings(&[
            "  com.b.app ",
            "",
            "com.a.app",
            "COM.B.APP",
            "   ",
            "Foo",
            "foo",
        ]));
        assert_eq!(normalized, strings(&["com.b.app", "com.a.app", "Foo"]));
    }

    #[test]
    fn gate_clones_share_state() {
        let gate = CaptureGate::new(true, Vec::new());
        let watcher_side = gate.clone();
        assert!(watcher_side.is_enabled());

        gate.set_enabled(false);
        assert!(!watcher_side.is_enabled(), "克隆必须共享同一个开关");
        assert_eq!(
            watcher_side.skip_reason(&[], None, None),
            Some(SkipReason::Paused)
        );

        gate.set_enabled(true);
        gate.set_excluded_apps(strings(&["com.foo.bar"]));
        assert!(watcher_side.is_excluded(Some("com.FOO.bar"), None));
        assert_eq!(
            watcher_side.skip_reason(&[], Some("com.foo.bar"), None),
            Some(SkipReason::ExcludedApp)
        );
        assert_eq!(watcher_side.skip_reason(&[], Some("com.other"), None), None);
    }

    fn item(name: Option<&str>, bundle_id: Option<&str>) -> ClipboardItem {
        let now = chrono::Utc::now();
        ClipboardItem {
            id: crate::domain::model::ClipboardItemId::new(),
            content_type: crate::domain::model::ContentType::Text,
            content_text: "x".into(),
            fingerprint: "fp".into(),
            group_id: None,
            created_at: now,
            updated_at: now,
            last_copied_at: now,
            source_app: name.map(str::to_string),
            source_url: None,
            source_bundle_id: bundle_id.map(str::to_string),
            source_app_path: None,
            legacy_id: None,
        }
    }

    #[test]
    fn distinct_source_apps_dedupes_in_order() {
        let items = vec![
            item(Some("Safari"), Some("com.apple.Safari")),
            item(Some("Safari 浏览器"), Some("COM.APPLE.SAFARI")),
            item(Some("Legacy"), None),
            item(Some("legacy"), None),
            item(None, None),
            item(Some("  "), Some(" ")),
            item(Some("Code"), Some("com.microsoft.VSCode")),
        ];
        let apps = distinct_source_apps(&items, 10);
        assert_eq!(
            apps,
            vec![
                SourceApp {
                    name: Some("Safari".into()),
                    bundle_id: Some("com.apple.Safari".into())
                },
                SourceApp {
                    name: Some("Legacy".into()),
                    bundle_id: None
                },
                SourceApp {
                    name: Some("Code".into()),
                    bundle_id: Some("com.microsoft.VSCode".into())
                },
            ]
        );
        assert_eq!(distinct_source_apps(&items, 1).len(), 1);
    }
}
